def _set_logger(logger):
    global _LOGGER
    _LOGGER = logger


def _log(msg):
    text = "[advanced_search] %s" % msg
    try:
        from android.util import Log
        Log.i("plugin.advanced_search", text)
    except Exception:
        pass
    if _LOGGER is not None:
        try:
            _LOGGER.info(text)
            return
        except Exception:
            pass
    try:
        from log_utils import get_logger
        get_logger("advanced_search").info(text)
        return
    except Exception:
        pass
    try:
        from android_utils import log
        log(text)
    except Exception:
        pass


def app_files_dir():
    try:
        return str(ApplicationLoader.applicationContext.getFilesDir().getAbsolutePath())
    except Exception:
        return None


def cache_db_path(account=0):
    base = app_files_dir()
    if not base:
        return None
    try:
        acc = int(account)
        if acc < 0:
            return None
    except Exception:
        return None
    if acc > 0:
        return "%s/account%d/cache4.db" % (base, acc)
    return "%s/cache4.db" % base


def restricted_dids_from_db(account=0, cancelled=None):
    """从本地 cache4.db 找出「含 porn 提示消息」的对话 id（负数）。

    这是跨客户端兜底判据：AyuGram 等构建里 TLRPC$Chat.restricted 恒为 false，
    只能用这条。命中集合会包含少量"只是被转发过一条被拦内容"的普通频道，
    多检索几个对话不会产生错误结果，可接受。

    返回值语义（v2.2 起）：list = 扫描成功（可能为空）；None = 扫描失败，调用方应重试。
    """
    path = cache_db_path(account)
    if cancelled is not None and cancelled():
        return None
    if not path or not os.path.exists(path):
        return None
    started = time.time()
    ordered = []
    try:
        import sqlite3
        from urllib.parse import quote
        # 只读 URI：限制写入与误创建；不承诺零锁冲突，也不使用 immutable=1 读取正在变化的热库
        uri_path = quote(path.replace("\\", "/"), safe="/:")
        con = sqlite3.connect("file:%s?mode=ro" % uri_path, uri=True, timeout=1.5)
        try:
            if cancelled is not None:
                con.set_progress_handler(lambda: int(cancelled()), 1000)
            try:
                con.execute("PRAGMA busy_timeout=1500")
                con.execute("PRAGMA query_only=ON")
            except Exception as exc:
                _log("设置只读 PRAGMA 失败（继续扫描）: %s: %s" % (type(exc).__name__, exc))
            # ASCII 标记按 bytes 传入，instr 走二进制比较（不受 NUL 截断影响）
            marker = PORN_MARKER.encode("utf-8")
            # v3.41 / O9：负数约束（d.did < 0）前移到外层，内层用 EXISTS 按
            # messages_v2 的主键前缀 (uid, mid) 关联，只对负数对话做索引查找，
            # 而不是先全表扫描 messages_v2 再在 Python 里求交集。
            # 是否真的命中索引以真机 EXPLAIN QUERY PLAN 为准，不在此做性能承诺。
            # 保留完整本地命中索引；范围过滤后的24个受限优先配额由Java搜索调度分配。
            for (did,) in con.execute(
                    "select d.did from dialogs d "
                    "where d.did < 0 and exists ("
                    "select 1 from messages_v2 m "
                    "where m.uid = d.did and instr(m.data, ?) > 0) "
                    "order by d.date desc",
                    (marker,)):
                try:
                    ordered.append(int(did))
                except Exception:
                    continue
        finally:
            try:
                con.close()
            except Exception:
                pass
    except Exception as exc:
        _log("cache4.db 扫描失败: %s: %s" % (type(exc).__name__, exc))
        return None
    _log("本地库扫描: 命中 %d 个对话, 耗时 %.2fs (account=%s)"
         % (len(ordered), time.time() - started, account))
    return ordered
