def _open_hint_url(context=None):
    """用宿主的 Browser.openUrl 打开参考链接（ChipFolders.plugin 同款写法）。

    为什么不用自己拼 ACTION_VIEW Intent：宿主会按自己的策略决定「应用内打开 / 外部浏览器 / 域名白名单」，
    行为与 Telegram 里点普通链接一致，也不需要额外权限。
    """
    try:
        from android_utils import run_on_ui_thread
        from org.telegram.messenger.browser import Browser

        act = context
        if act is None or not hasattr(act, "startActivity"):
            act = None
        if act is None:
            try:
                from client_utils import get_last_fragment
                frag = get_last_fragment()
                if frag is not None:
                    act = frag.getParentActivity()
            except Exception:
                act = None
        if act is None:
            act = ApplicationLoader.applicationContext
        run_on_ui_thread(lambda: Browser.openUrl(act, HINT_URL))
        _p("open hint url: %s" % HINT_URL)
    except Exception as exc:
        _p("open hint url failed: %s: %s" % (type(exc).__name__, exc))


