def _signed32(v):
    """Java 的 int 是 32 位有符号数。

    Theme.getColor() 返回的颜色（如 0xFF3390EC = 4281544940）超出 int32 范围，
    直接用 Python int 传给 Java 方法会抛
    OverflowError: value too large to convert to int32_t。
    """

    try:
        v = int(v) & 0xFFFFFFFF
    except Exception:
        return 0
    return v - 0x100000000 if v > 0x7FFFFFFF else v


def _post(fn, delay_ms=0):
    """在 UI 线程执行（可延迟）。

    android_utils.run_on_ui_thread(fn, delay) 底层是 Handler.postDelayed，
    不再需要 threading.Thread + time.sleep 那种「每次调用建一个 OS 线程」的做法。
    老 SDK 若只接受一个参数，则回退到 android_utils.R + AndroidUtilities.runOnUIThread。
    """

    try:
        d = int(delay_ms) if delay_ms and delay_ms > 0 else 0
    except Exception:
        d = 0

    try:
        if d > 0:
            run_on_ui_thread(fn, d)
        else:
            run_on_ui_thread(fn)
        return
    except TypeError:
        # 该版本 run_on_ui_thread 不接受 delay 参数
        pass
    except Exception as e:
        _p("post error: %s: %s" % (type(e).__name__, e))
        return

    if d > 0 and _RunnableProxy is not None:
        try:
            AndroidUtilities.runOnUIThread(_RunnableProxy(fn), d)
            return
        except Exception as e:
            _p("post delayed fallback failed: %s: %s" % (type(e).__name__, e))

    try:
        run_on_ui_thread(fn)
    except Exception as e:
        _p("post fallback error: %s: %s" % (type(e).__name__, e))


